function sortedSquares(values) {
  const result = new Array(values.length)
  let left = 0
  let right = values.length - 1
  for (let write = values.length - 1; write >= 0; write--) {
    const a = values[left] * values[left]
    const b = values[right] * values[right]
    if (a > b) { result[write] = a; left++ } else { result[write] = b; right-- }
  }
  return result
}

