def sorted_squares(values):
    result = [0] * len(values)
    left, right = 0, len(values) - 1
    for write in range(len(values) - 1, -1, -1):
        a, b = values[left] * values[left], values[right] * values[right]
        if a > b:
            result[write] = a
            left += 1
        else:
            result[write] = b
            right -= 1
    return result
